 auto bottom=new QHBoxLayout;layout->addLayout(bottom);auto stepBox=new QGroupBox("Pas de réglage");auto stepLayout=new QVBoxLayout(stepBox);auto step=new QComboBox;step->setObjectName("frequencyStep");for(qint64 hz:{1LL,10LL,100LL,1000LL,2500LL,5000LL,6250LL,8330LL,10000LL,12500LL,25000LL,50000LL,100000LL,1000000LL})step->addItem(hz<1000?QString::number(hz)+" Hz":hz<1000000?QString::number(hz/1000.0,'g',6)+" kHz":"1 MHz",hz);qint64 chosen=qMax<qint64>(1,settings.value("stepHz",1000).toLongLong());int index=step->findData(chosen);if(index<0){step->addItem(QString::number(chosen)+" Hz",chosen);index=step->count()-1;}step->setCurrentIndex(index);input->stepHz=chosen;step->addItem("Pas personnalisé…",0);stepLayout->addWidget(step);bottom->addWidget(stepBox,1);connect(step,&QComboBox::activated,&dialog,[&](int i){auto hz=step->itemData(i).toLongLong();if(!hz){bool ok;int custom=QInputDialog::getInt(&dialog,"Pas personnalisé","Pas positif en Hz",int(qMin<qint64>(input->stepHz,INT_MAX)),1,INT_MAX,1,&ok);if(!ok){step->setCurrentIndex(step->findData(input->stepHz));return;}hz=custom;step->insertItem(step->count()-1,QString::number(hz)+" Hz",hz);step->setCurrentIndex(step->count()-2);}input->stepHz=hz;});
